# Generated by house_price_prediction.ipynb (Step 5). Used by the saved model and app.py.


def add_age_features(houses):
    """Add HouseAge and YearsSinceRemodel, measured at the sale (valuation) year."""
    houses = houses.copy()
    houses["HouseAge"] = houses["YrSold"] - houses["YearBuilt"]
    houses["YearsSinceRemodel"] = houses["YrSold"] - houses["YearRemodAdd"]
    return houses
